import os,glob,re
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), G['Demo pair 1 input'][0][:5] if 'Demo pair 1 input' in G else None)

from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    cnt=Counter(v for r in g for v in r)
    frame=cnt.most_common(1)[0][0]
    ccnt=Counter(v for r in g for v in r if v not in (0,frame))
    main=ccnt.most_common(1)[0][0]
    colors=[c for c in ccnt if c!=main]
    out=[r[:] for r in g]
    centers=[(i,j) for i in range(H) for j in range(W) if g[i][j] in colors]
    for c in colors:
        pts=sorted(p for p in centers if g[p[0]][p[1]]==c)
        for a,b in zip(pts,pts[1:]):
            (r1,c1),(r2,c2)=a,b
            if r1==r2:
                for j in range(min(c1,c2)+1,max(c1,c2)):
                    if out[r1][j]==0: out[r1][j]=c
            if c1==c2:
                for i in range(min(r1,r2)+1,max(r1,r2)):
                    if out[i][c1]==0: out[i][c1]=c
    return out
